function translate(){document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';$('language').textContent=lang==='he'?'English':'עברית';document.querySelectorAll('[data-t]').forEach(el=>{el.textContent=tr(el.dataset.t);});$('objectSearchQuery').placeholder=lang==='he'?'מצאו טנדרים אדומים':'Find red pickup trucks';$('imageSearch').placeholder=tr('imageSearchPlaceholder');for(const option of $('field3').options)option.textContent=tr(option.value);$('timezoneMap').setAttribute('aria-label',tr('timezoneMapHelp'));updateModeOptions();if($('missions').options.length)$('missions').options[0].textContent=tr('choose');drawTimezoneMap();previewTimezone();render();renderJobs();renderVideo();renderLearningReport();updateDesktopAlertsButton();}
function updateModeOptions(){const keys=$('inputType').value==='images'?['general_traffic','object_search','license_plate']:['video_traffic','object_search','license_plate'];const old=$('analysisMode').value;$('analysisMode').replaceChildren(...keys.map(key=>new Option(tr(({general_traffic:'generalTraffic',object_search:'objectSearch',license_plate:'licensePlate',video_traffic:'videoTraffic'})[key]),key)));if(keys.includes(old))$('analysisMode').value=old;}
const timezoneBounds={west:18,east:65,south:24,north:72,width:900,height:520},countryZones={Israel:'Asia/Jerusalem',Iran:'Asia/Tehran',Lebanon:'Asia/Beirut',Latvia:'Europe/Riga',Finland:'Europe/Helsinki'};
const mapX=lon=>(lon-timezoneBounds.west)/(timezoneBounds.east-timezoneBounds.west)*timezoneBounds.width,mapY=lat=>(timezoneBounds.north-lat)/(timezoneBounds.north-timezoneBounds.south)*timezoneBounds.height;
function mapPolygons(feature){return feature.geometry.type==='Polygon'?[feature.geometry.coordinates]:feature.geometry.coordinates;}
function mapRings(feature){return mapPolygons(feature).flatMap(polygon=>polygon.flat());}
function timezonePath(feature){return mapPolygons(feature).map(polygon=>polygon.map(ring=>ring.map((point,index)=>`${index?'L':'M'}${mapX(point[0]).toFixed(1)},${mapY(point[1]).toFixed(1)}`).join(' ')+' Z').join(' ')).join(' ');}
function drawTimezoneMap(){const svg=$('timezoneMap');if(!svg)return;svg.replaceChildren();const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','900');bg.setAttribute('height','520');bg.setAttribute('class','map-water');svg.append(bg);for(let lon=20;lon<=60;lon+=10){const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('x1',mapX(lon));line.setAttribute('x2',mapX(lon));line.setAttribute('y1',mapY(timezoneBounds.north));line.setAttribute('y2',mapY(timezoneBounds.south));line.setAttribute('class','map-grid');svg.append(line);const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x',mapX(lon)+3);label.setAttribute('y',510);label.setAttribute('class','map-coordinate');label.textContent=`${lon}°`;svg.append(label);}for(let lat=30;lat<=70;lat+=10){const line=document.createElementNS(svg.namespaceURI,'line');line.setAttribute('x1',0);line.setAttribute('x2',900);line.setAttribute('y1',mapY(lat));line.setAttribute('y2',mapY(lat));line.setAttribute('class','map-grid');svg.append(line);const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x',4);label.setAttribute('y',mapY(lat)-3);label.setAttribute('class','map-coordinate');label.textContent=`${lat}°`;svg.append(label);}for(const feature of timezoneFeatures){const name=feature.properties.name,polygon=document.createElementNS(svg.namespaceURI,'path');polygon.setAttribute('d',timezonePath(feature));polygon.setAttribute('class','timezone-country'+($('field3').value===name?' selected':''));polygon.dataset.country=name;polygon.setAttribute('fill-rule','evenodd');svg.append(polygon);const pts=mapRings(feature),xs=pts.map(p=>p[0]),ys=pts.map(p=>p[1]),label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x',mapX((Math.min(...xs)+Math.max(...xs))/2));label.setAttribute('y',mapY((Math.min(...ys)+Math.max(...ys))/2));label.setAttribute('class','map-country-label');label.textContent=tr(name);svg.append(label);}if(timezoneMarker){const dot=document.createElementNS(svg.namespaceURI,'circle');dot.setAttribute('cx',mapX(timezoneMarker[0]));dot.setAttribute('cy',mapY(timezoneMarker[1]));dot.setAttribute('r','7');dot.setAttribute('class','map-marker');svg.append(dot);}}
function ringContains(point,ring){let inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const [xi,yi]=ring[i],[xj,yj]=ring[j];if(((yi>point[1])!==(yj>point[1]))&&(point[0]<(xj-xi)*(point[1]-yi)/(yj-yi)+xi))inside=!inside;}return inside;}
function containsMapPoint(feature,point){return mapPolygons(feature).some(poly=>ringContains(point,poly[0])&&!poly.slice(1).some(hole=>ringContains(point,hole)));}
function chooseTimezoneCountry(feature,lon,lat){$('field3').value=feature.properties.name;$('field4').value=feature.properties.timezone;$('location').value=`${lat.toFixed(4)}, ${lon.toFixed(4)}`;timezoneMarker=[lon,lat];$('timezoneMapStatus').textContent=`${tr('timezoneMapSelected')}: ${tr(feature.properties.name)} · ${feature.properties.timezone} · ${$('location').value}`;drawTimezoneMap();previewTimezone();}
function previewTimezone(){const out=$('timezoneOffsetPreview'),raw=$('timezonePreviewUtc')?.value,zone=$('field4').value;try{if(!raw){out.textContent=tr('timezonePreviewEmpty');return;}const date=new Date(raw+'Z');if(Number.isNaN(date.getTime()))throw new Error();out.textContent=new Intl.DateTimeFormat(lang==='he'?'he-IL':'en-GB',{timeZone:zone,weekday:'long',year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(date);}catch{out.textContent=tr('timezonePreviewEmpty');}}
async function loadTimezoneMap(){const svg=$('timezoneMap');if(!svg)return;const now=new Date(),utc=new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16);$('timezonePreviewUtc').value=utc;try{const response=await fetch('/timezone-countries.json');if(!response.ok)throw new Error();const data=await response.json();timezoneFeatures=data.features;drawTimezoneMap();$('timezoneMapStatus').textContent=tr('timezoneMapStatus');previewTimezone();}catch{$('timezoneMapStatus').textContent=tr('timezoneMapUnavailable');}}
function countryChanged(){const name=$('field3').value;$('field4').value=countryZones[name]||$('field4').value;timezoneMarker=null;drawTimezoneMap();previewTimezone();}
function syncMissionConfig(){const selected=missions.find(x=>x.id===mission),path=$('importForm').elements.path;path.value=selected?.source_root||'';path.readOnly=!!selected?.source_root;const unavailable=!!selected&&selected.input_type!=='images';$('importForm').querySelector('button').disabled=unavailable;const savePolicy=$('saveVideoMonitorPolicy');if(savePolicy)savePolicy.hidden=!(selected?.processing_mode==='continuous'&&selected?.input_type==='videos'&&selected?.analysis_mode==='video_traffic');syncWorkflow();}
function syncWorkflow(){const selected=missions.find(x=>x.id===mission),video=selected?.input_type==='videos';$('openPlateReview').disabled=!selected||selected.analysis_mode!=='license_plate';$('detectCurrentPlates').hidden=video;$('detectVideoPlates').hidden=!video;$('bulkApprove').hidden=video||selected?.analysis_mode!=='general_traffic';$('bulkApprovalDetails').hidden=video||selected?.analysis_mode!=='general_traffic';$('videoWorkflow').hidden=!video;$('objectSearchPanel').hidden=video;document.querySelectorAll('.content > :not(#videoWorkflow)').forEach(el=>el.hidden=video);$('schedulePanel').hidden=video;$('viewPanel').hidden=video;$('importForm').closest('details').hidden=video;$('importForm').closest('details').open=!video;document.querySelector('summary[data-t="detection"]').closest('details').hidden=video;$('videoSourceRoot').textContent=selected?.source_root||tr('videoSourceRootEmpty');const supported=video&&selected.analysis_mode==='video_traffic';$('videoModeNote').textContent=video&&selected.analysis_mode==='license_plate'?tr('videoPlateNote'):video&&!supported?tr('videoModeUnsupported'):'';for(const control of $('videoRunForm').elements)control.disabled=!supported;const sourceButton=$('videoSourceForm').querySelector('button');sourceButton.disabled=!video||!selected.source_root;if(video)refreshVideo().catch(error=>message(error.message,true));}
async function refreshVideo(){if(videoRefreshing||!mission||missions.find(x=>x.id===mission)?.input_type!=='videos')return;videoRefreshing=true;const current=mission;try{const [sources,runs,clips,eventTables]=await Promise.all([api('/api/video/sources?mission='+encodeURIComponent(current)),api('/api/video/runs?mission='+encodeURIComponent(current)),api('/api/video/clips?mission='+encodeURIComponent(current)),api('/api/video/event-exports?mission='+encodeURIComponent(current))]);if(current!==mission)return;videoSources=sources;videoRuns=runs;videoClipExports=clips;videoEventTableExports=eventTables;if(!videoSources.some(item=>item.id===$('videoSourceSelect').value))$('videoSourceSelect').value=videoSources[0]?.id||'';if(!videoRuns.some(item=>item.id===videoRunId))videoRunId=videoRuns[0]?.id||'';renderVideo();renderVideoClips();renderVideoEventExports();const run=videoRuns.find(item=>item.id===videoRunId),signature=run?`${run.id}:${run.status}:${run.frames_done}:${run.updated}`:'';if(signature!==videoEventSignature){videoEventSignature=signature;videoEventOffset=0;await loadVideoEvents();}if(!$('plateWorkflow').hidden)await refreshPlateCrops();}finally{videoRefreshing=false;}}
function clearVideoOverlay(){videoOverlayRequest++;$('videoEventOverlay').replaceChildren();}
function syncVideoPlayer(sourceId,seekTo=null){const player=$('videoPlayer'),wrap=$('videoPlayerWrap'),source=videoSources.find(item=>item.id===sourceId);if(!source){player.pause();player.removeAttribute('src');player.load();wrap.hidden=true;videoPlayerSourceKey='';videoPendingSeek=null;clearVideoOverlay();return;}wrap.hidden=false;const key=`${mission}:${source.id}`;if(videoPlayerSourceKey!==key){videoPlayerSourceKey=key;clearVideoOverlay();player.src=`/api/video/media?mission=${encodeURIComponent(mission)}&source=${encodeURIComponent(source.id)}`;player.load();}if(seekTo!==null){if(player.readyState>=1){player.currentTime=Math.max(0,seekTo);videoPendingSeek=null;}else videoPendingSeek=seekTo;}}
async function updateVideoOverlay(){const player=$('videoPlayer'),svg=$('videoEventOverlay'),run=videoRuns.find(item=>item.id===videoRunId),sourceId=$('videoSourceSelect').value,request=++videoOverlayRequest;if(!run||run.source_id!==sourceId||player.readyState<1){svg.replaceChildren();return;}const current=player.currentTime;try{const result=await api(`/api/video/frame-overlay?mission=${encodeURIComponent(mission)}&run=${encodeURIComponent(run.id)}&seconds=${encodeURIComponent(current)}`);if(request!==videoOverlayRequest||run.id!==videoRunId||sourceId!==$('videoSourceSelect').value||Math.abs(player.currentTime-current)>.35)return;svg.replaceChildren();if(result.source_id!==sourceId||!result.frame)return;const ns='http://www.w3.org/2000/svg';for(const detection of result.detections){const [x,y,w,h]=detection.box;const rect=document.createElementNS(ns,'rect');rect.setAttribute('x',x*1000);rect.setAttribute('y',y*1000);rect.setAttribute('width',w*1000);rect.setAttribute('height',h*1000);rect.setAttribute('class','video-detection-box');svg.append(rect);const label=document.createElementNS(ns,'text');label.setAttribute('x',x*1000);label.setAttribute('y',Math.max(24,y*1000-8));label.setAttribute('class','video-detection-label');label.textContent=`${detection.label}${detection.track_id?' · '+detection.track_id.split(':').pop():''}`;svg.append(label);}}catch(error){if(request===videoOverlayRequest)svg.replaceChildren();}}
$('videoPlayer').addEventListener('loadedmetadata',()=>{if(videoPendingSeek!==null){$('videoPlayer').currentTime=Math.max(0,videoPendingSeek);videoPendingSeek=null;}updateVideoOverlay();});
$('videoPlayer').addEventListener('timeupdate',updateVideoOverlay);$('videoPlayer').addEventListener('seeking',clearVideoOverlay);
function renderVideo(){const sources=$('videoSourceSelect'),runs=$('videoRunSelect');if(!sources||!runs)return;const sourceId=sources.value;sources.replaceChildren(...(videoSources.length?videoSources.map(item=>new Option(`${item.source_relative_path} · ${item.recording_start_utc||tr('videoRunUnknown')}`,item.id)):[new Option(tr('videoSourceRequired'),'')]));if(videoSources.some(item=>item.id===sourceId))sources.value=sourceId;const selectedSource=videoSources.find(item=>item.id===sources.value),probe=selectedSource?.metadata?.media_probe,info=probe?.metadata;let metadataText=tr('videoMetadataUnavailable');if(probe?.status==='available'&&info){const duration=info.duration_pts!==null&&info.duration_pts!==undefined&&info.stream_time_base_num&&info.stream_time_base_den?(Number(info.duration_pts)*Number(info.stream_time_base_num)/Number(info.stream_time_base_den)).toFixed(2)+' s':tr('videoMetadataUnknown');const rate=info.average_rate_num&&info.average_rate_den?(Number(info.average_rate_num)/Number(info.average_rate_den)).toFixed(3)+' fps':tr('videoMetadataUnknown');metadataText=`${tr('videoMetadata')}: ${info.codec_name} · ${info.format_name} · ${info.width}×${info.height} · ${rate} · ${duration} · ${info.frame_count||tr('videoMetadataUnknown')} ${tr('videoFrames')}${selectedSource.recording_start_utc?' · UTC '+selectedSource.recording_start_utc:' · '+tr('videoUtcUnverified')}`;}else if(probe?.error){metadataText=`${tr('videoMetadataUnavailable')}: ${probe.error}`;}$('videoMediaMetadata').textContent=metadataText;syncVideoPlayer(sources.value);const runId=runs.value;runs.replaceChildren(...(videoRuns.length?videoRuns.map(item=>new Option(`${tr(item.status)} · ${item.frames_done}/${item.total_frames??'?' } · ${item.id.slice(0,8)}`,item.id)):[new Option(tr('videoRunUnknown'),'')]));if(videoRuns.some(item=>item.id===videoRunId))runs.value=videoRunId;else if(videoRuns.some(item=>item.id===runId)){videoRunId=runId;runs.value=runId;}const run=videoRuns.find(item=>item.id===videoRunId),active=run&&['queued','running'].includes(run.status);$('cancelVideoRun').hidden=!active;$('cancelVideoRun').disabled=!!run?.cancel_requested;$('resumeVideoRun').hidden=!run||!['failed','cancelled'].includes(run.status);$('resumeVideoRun').disabled=!!videoRuns.some(item=>['queued','running'].includes(item.status));$('videoRunStatus').textContent=run?`${tr('videoStatus')}: ${tr(run.status)} · ${tr(run.stage)} · ${run.frames_done} ${tr('videoRunProgress')} / ${run.total_frames??'?'}`:tr('videoRunUnknown');$('videoProgress').max=Math.max(1,run?.total_frames||1);$('videoProgress').value=run?.total_frames?(run.frames_done||0):0;$('videoRunError').textContent=run?.error||'';$('previousVideoEvents').disabled=videoEventOffset<=0;$('nextVideoEvents').disabled=videoEvents.length<100;}
function renderVideoClips(){const list=$('videoClipExports');if(!list)return;list.replaceChildren();for(const clip of videoClipExports){const item=document.createElement('li');const label=document.createElement('span');label.textContent=`${clip.status} · ${clip.frame_count||0} frames · ${clip.id.slice(0,8)}`;item.append(label);if(clip.status==='completed'){const link=document.createElement('a');link.href=clip.download_url;link.textContent=' · '+clip.output_path.split(/[\\/]/).pop();link.setAttribute('download','');item.append(link);}else if(clip.error){const error=document.createElement('span');error.className='error';error.textContent=' · '+clip.error;item.append(error);}list.append(item);}}
