let learningInfo=null;
function renderLearningReport(){
 const target=$('learningReport');if(!target||!learningInfo){if(target)target.textContent='';return;}
 const inv=learningInfo.inventory||{},candidates=learningInfo.candidates||[];
 const imageCount=role=>new Set((inv[role]||[]).map(row=>row.image_id)).size;
 const lines=[`${tr('trainRegions')}: ${(inv.training||[]).length} · ${inv.eligible_training_images||0} ${tr('candidateImages').toLowerCase()}`,
  `${tr('validationRegions')}: ${(inv.validation||[]).length} · ${imageCount('validation')} images`,
  `${tr('testRegions')}: ${(inv.test||[]).length} · ${imageCount('test')} images`,
  `${tr('excludedRegions')}: ${(inv.excluded||[]).length}`,
  `${tr('candidateClasses')}: ${(inv.classes||[]).join(', ')||tr('unknown')}`,
  tr('testHoldoutNote')];
 const selected=candidates.find(item=>item.id===$('nightHead').value);
 if(selected){
  let report={};try{report=typeof selected.report==='string'?JSON.parse(selected.report):(selected.report||{});}catch{report={};}
  lines.push('',`${tr('candidateDetails')}: ${selected.id} · ${selected.status} · ${selected.created||''}`,
   `${tr('candidateArtifactHash')}: ${selected.artifact_hash||tr('unknown')}`);
  if(report.training_regions!==undefined)lines.push(`${tr('candidateFitRegions')}: ${report.training_regions}`);
  if(report.training_images!==undefined)lines.push(`${tr('candidateImages')}: ${report.training_images}`);
  if(report.classes)lines.push(`${tr('candidateClasses')}: ${report.classes.join(', ')}`);
  if(report.validation?.per_class){lines.push(`${tr('candidateValidation')}:`);for(const [label,metrics] of Object.entries(report.validation.per_class))lines.push(`  ${label}: precision ${Number(metrics.precision).toFixed(3)} · recall ${Number(metrics.recall).toFixed(3)} · F1 ${Number(metrics.f1).toFixed(3)} · n=${metrics.support}`);}
  else if(report.validation_unavailable_reason)lines.push(tr('candidateNoValidation'));
  const testReports=(learningInfo.evaluation?.evaluations||[]).filter(item=>item.candidate_id===selected.id&&item.status==='completed').slice(-3);
  for(const evaluation of testReports){const result=evaluation.report||{};lines.push('',`${tr('testEvaluationTitle')} · ${evaluation.created||''} · ${tr('testEvaluationCandidate')}: ${selected.id.slice(0,8)}`,`${tr('testEvaluationRegions')}: ${result.regions||0} · ${tr('testEvaluationAccuracy')}: ${Number(result.accuracy||0).toFixed(3)} · ${tr('testEvaluationMacroF1')}: ${Number(result.macro_f1||0).toFixed(3)}`);for(const [label,metrics] of Object.entries(result.per_class||{}))lines.push(`  ${label}: precision ${Number(metrics.precision).toFixed(3)} · recall ${Number(metrics.recall).toFixed(3)} · F1 ${Number(metrics.f1).toFixed(3)} · n=${metrics.support}`);}
  if(selected.error)lines.push(`${tr('failed')}: ${String(selected.error).slice(0,240)}`);
 }
 const recent=candidates.slice(0,8);
 if(recent.length){lines.push('',`${tr('candidateHistory')}:`);for(const item of recent)lines.push(`  ${item.id.slice(0,8)} · ${item.status} · ${item.created||''}${item.error?' · '+String(item.error).slice(0,140):''}`);}
 target.textContent=lines.join('\n');
}
function renderLearningCapabilities(){
 const algorithms=learningInfo?.capabilities||[];let panel=$('algorithmCapabilitiesPanel');
 if(!panel&&algorithms.length){panel=document.createElement('details');panel.id='algorithmCapabilitiesPanel';const summary=document.createElement('summary');summary.textContent=tr('learningCapabilities');const list=document.createElement('ul');list.id='algorithmCapabilities';list.className='capability-list';list.setAttribute('aria-live','polite');panel.append(summary,list);$('learningReport').after(panel);}
 if(!panel)return;panel.hidden=!algorithms.length;panel.querySelector('summary').textContent=tr('learningCapabilities');const list=panel.querySelector('#algorithmCapabilities');if(!list)return;list.replaceChildren();
 for(const algorithm of algorithms){const item=document.createElement('li'),name=document.createElement('strong'),role=document.createElement('p'),methodTitle=document.createElement('p'),methods=document.createElement('ul');name.textContent=algorithm.name;role.textContent=`${tr('capabilityRole')}: ${algorithm.role}`;methodTitle.textContent=tr('capabilityMethods');item.append(name,role,methodTitle);for(const [method,state] of Object.entries(algorithm.methods||{})){const entry=document.createElement('li');entry.textContent=`${tr('method_'+method)}: ${tr('cap_'+state)}`;methods.append(entry);}item.append(methods);for(const [key,label] of [['available_controls','capabilityControls'],['limitations','capabilityLimitations']]){const paragraph=document.createElement('p');paragraph.textContent=`${tr(label)}: ${(algorithm[key]||[]).join('; ')}`;item.append(paragraph);}list.append(item);}
}
async function refreshLearning(){if(!mission){learningInfo=null;renderLearningReport();renderLearningCapabilities();return;}const m=mission;const info=await api('/api/night-learning?mission='+mission);if(m!==mission)return;learningInfo=info;const selected=$('nightHead').value;$('nightHead').replaceChildren(new Option(tr('noHead'),''),...info.candidates.filter(c=>c.status==='completed').map(c=>new Option(c.id.slice(0,8)+' · candidate',c.id)));$('nightHead').value=info.candidates.some(c=>c.id===selected&&c.status==='completed')?selected:'';const inv=info.inventory||{};$('learningStatus').textContent=`${(inv.training||[]).length} ${tr('trainingCount')} · ${inv.eligible_training_images||0} images · ${tr('validationRegions')}: ${(inv.validation||[]).length} · ${tr('testRegions')}: ${(inv.test||[]).length}`;const running=info.candidates.find(c=>c.status==='running');if(running)$('learningStatus').textContent+=` · ${running.progress}%`;const testState=info.evaluation||{},selectedCandidate=info.candidates.some(c=>c.id===$('nightHead').value&&c.status==='completed');$('evaluateNightTest').disabled=!selectedCandidate||!testState.test_regions||testState.already_evaluated;renderLearningReport();renderLearningCapabilities();}
