$('trainNight').onclick=()=>action(async()=>{if(!leave())return;$('trainNight').disabled=true;try{const result=await api('/api/night-learning/train',{mission});message(result.message||('Training: '+result.status));await refreshLearning();}finally{$('trainNight').disabled=false;}});
$('evaluateNightTest').onclick=()=>action(async()=>{const candidateId=$('nightHead').value;if(!candidateId)throw new Error(tr('candidateDetails'));const evaluation=learningInfo?.evaluation||{};if(!evaluation.test_regions)throw new Error(tr('testEvaluationNone'));if(evaluation.already_evaluated)throw new Error(tr('testEvaluationLocked'));if(!window.confirm(tr('testEvaluationConfirm')))return;const operator=$('operator').value.trim();if(!operator)throw new Error(tr('operator')+' required');$('evaluateNightTest').disabled=true;try{const result=await api('/api/night-learning/evaluate-test',{mission,candidate_id:candidateId,operator});message(`${tr('testEvaluationTitle')} · ${result.report.regions} · F1 ${Number(result.report.macro_f1).toFixed(3)}`);await refreshLearning();}finally{const state=learningInfo?.evaluation||{};$('evaluateNightTest').disabled=!$('nightHead').value||!state.test_regions||state.already_evaluated;}});
