async function refreshBulkApprovals(){const selected=missions.find(item=>item.id===mission),list=$('bulkApprovalHistoryList');if(!list)return;const supported=selected?.input_type==='images'&&selected?.analysis_mode==='general_traffic';$('bulkApprovalDetails').hidden=!supported;if(!supported){list.replaceChildren();return;}const rows=await api('/api/bulk-approvals?mission='+encodeURIComponent(mission));if(selected!==missions.find(item=>item.id===mission))return;list.replaceChildren();if(!rows.length){const empty=document.createElement('li');empty.textContent=tr('bulkApprovalEmpty');list.append(empty);return;}for(const row of rows){const item=document.createElement('li');item.textContent=`${row.status} · ${row.image_count} ${tr('images')} · ${row.inference_run.slice(0,8)} · ${row.operator} · ${row.id.slice(0,8)} · ${tr('bulkApprovalCaveat')}`;list.append(item);}}
function renderJobs(){const select=$('inferenceRuns');select.replaceChildren(new Option(tr('latest'),''),...jobs.map(j=>new Option(`${tr(j.status)} · ${j.created.slice(0,16)} · ${j.id.slice(0,8)}`,j.id)));select.value=selectedRun;const job=jobs.find(j=>j.id===selectedRun)||jobs[0];activeRun=jobs.find(j=>['queued','running'].includes(j.status))||null;const selected=missions.find(x=>x.id===mission);$('startInference').disabled=!mission||!!activeRun||selected?.input_type!=='images'||selected?.analysis_mode!=='general_traffic';$('bulkApprove').disabled=!job||job.status!=='completed'||job.done!==job.total||!!activeRun||job.roi_review_required||!images.length;$('inferenceProgress').hidden=!job;$('resumeInference').hidden=true;$('regionSnapshotWarning').hidden=!job?.roi_stale;$('roiRerun').hidden=!job?.roi_review_required||!!activeRun;$('roiRerun').disabled=!!activeRun;if(!job){$('roiRerun').hidden=true;return;}$('inferenceState').textContent=tr(job.status)+' · '+tr(job.stage);$('inferenceBar').max=job.total;$('inferenceBar').value=job.done;$('inferenceText').textContent=`${job.done} / ${job.total} (${Math.round(job.done/job.total*100)}%) · ${job.id}`;$('runError').textContent=job.error||'';$('regionSnapshotWarning').textContent=job.roi_stale?(job.roi_rerun_acknowledgment?`${tr('regionSnapshotRerunTracked')} ${job.roi_rerun_operator} · ${job.roi_rerun_id.slice(0,8)} · ${tr(job.roi_rerun_status)}`:`${tr('regionSnapshotChanged')} ${job.roi_changed_views.map(view=>view.view_name).join(', ')}. ${tr('roiSameInputs')}`):'';$('stopInference').hidden=!activeRun;$('stopInference').disabled=!!activeRun?.stop_requested;$('resumeInference').hidden=!!activeRun||!['failed','cancelled'].includes(job.status)||job.done>=job.total;}
async function poll(){if(!mission||polling)return;polling=true;const current=mission;try{if(missions.find(x=>x.id===mission)?.input_type==='videos'){await refreshVideo();await pollMonitoring();return;}const result=await api('/api/inference?mission='+mission);if(current!==mission)return;const before=JSON.stringify(jobs.map(j=>[j.id,j.done,j.status]));jobs=result;renderJobs();await pollMonitoring();await refreshLearning();if(before!==JSON.stringify(jobs.map(j=>[j.id,j.done,j.status]))&&!dirty&&!loading)await load(true);}catch(e){message(e.message,true);}finally{polling=false;}}
