async function refreshPlateCrops(imageId=null){
 if(!mission)return;
 const current=mission,selected=missions.find(item=>item.id===mission);
 $('plateFolderInfo').textContent=selected?.output_root?`${tr('plateSavedFolder')}: ${selected.output_root}/plate-crops/${mission}`:'';
 const url='/api/plates?mission='+encodeURIComponent(mission)+(imageId?'&image='+encodeURIComponent(imageId):'');
 const items=await api(url);if(current!==mission)return;
 const list=$('plateCrops');list.replaceChildren();
 if(!items.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=tr('plateEmpty');list.append(empty);return;}
 for(const item of items){const card=document.createElement('article');card.className='plate-card';
  const image=document.createElement('img');image.src='/api/plate-crop?mission='+encodeURIComponent(mission)+'&crop='+encodeURIComponent(item.id);image.alt=tr('plateReviewHeading');
  const context=document.createElement('img');context.className='plate-context';context.src=item.source_kind==='video'?'/api/plate-context?mission='+encodeURIComponent(mission)+'&crop='+encodeURIComponent(item.id):'/api/image?mission='+encodeURIComponent(mission)+'&image='+encodeURIComponent(item.image_id);context.alt=item.source_name;
  const meta=document.createElement('div');meta.className='plate-meta';
  const source=document.createElement('strong');source.textContent=`${tr('plateSource')}: ${item.source_name}`;
  const score=document.createElement('span');score.textContent=`${tr('plateConfidence')}: ${Number(item.confidence).toFixed(3)}`;const frameTime=document.createElement('span');if(item.source_kind==='video'){const seconds=item.time_base_den?item.pts*item.time_base_num/item.time_base_den:null;frameTime.textContent=`${tr('plateFrameTime')}: ${item.frame_index} · ${seconds===null?'?':seconds.toFixed(3)+'s'}${item.capture_utc?' · '+item.capture_utc:''}`;}
  const state=document.createElement('span');state.className='plate-state';state.textContent=tr(item.decision==='approved'?'plateApproved':item.decision==='rejected'?'plateRejected':'platePending');
  const controls=document.createElement('div');controls.className='plate-review-buttons';
  for(const [decision,key] of [['approved','plateApprove'],['rejected','plateReject']]){const button=document.createElement('button');button.type='button';button.textContent=tr(key);button.onclick=()=>action(async()=>{const operator=$('plateOperator').value.trim();if(!operator)throw new Error(tr('plateNeedOperator'));await api('/api/plates/review',{mission,crop_id:item.id,expected_revision:item.revision||0,decision,operator});await refreshPlateCrops();});controls.append(button);}
  const contextLabel=document.createElement('span');contextLabel.className='muted';contextLabel.textContent=item.source_name;meta.append(source,score);if(item.source_kind==='video')meta.append(frameTime);meta.append(state,controls);card.append(image,contextLabel,context,meta);list.append(card);
 }
}
$('lanLogout').onclick=()=>action(async()=>{const response=await fetch('/api/logout',{method:'POST',headers:{'X-Session-Token':token}});if(!response.ok)throw new Error(tr('logoutFailed'));location.reload();});
$('openPlateReview').onclick=()=>action(async()=>{if(!mission)throw new Error(tr('needMission'));$('mainWorkflow').hidden=true;$('plateWorkflow').hidden=false;const selected=missions.find(item=>item.id===mission);const isVideo=selected?.input_type==='videos';$('backToImages').textContent=isVideo?tr('backToVideo'):tr('backToImages');$('plateCurrentImage').textContent=isVideo?($('videoSourceSelect').selectedOptions[0]?.textContent||tr('videoSourceRequired')):(images[index]?images[index].name:tr('plateNeedImage'));await refreshPlateCrops();});
$('backToImages').onclick=()=>{$('plateWorkflow').hidden=true;$('mainWorkflow').hidden=false;syncWorkflow();};
$('detectVideoPlates').onclick=()=>action(async()=>{const sourceId=$('videoSourceSelect').value;if(!sourceId)throw new Error(tr('videoSourceRequired'));const result=await api('/api/plates/detect-video',{mission,source_id:sourceId});videoRunId=result.run;videoEventSignature='';$('plateNotice').textContent=`${tr('videoStatus')}: ${tr(result.status)} · ${result.run.slice(0,8)}`;await refreshVideo();});
$('detectCurrentPlates').onclick=()=>action(async()=>{const row=images[index];if(!row)throw new Error(tr('plateNeedImage'));$('plateCurrentImage').textContent=row.name;const items=await api('/api/plates/detect',{mission,image_id:row.id});$('plateNotice').textContent=`${tr('plateDetectionDone')}: ${items.length}`;await refreshPlateCrops();});
Object.assign(en,{videoOverlayHelp:'Saved boxes and track labels appear on analyzed frames only; the viewer does not interpolate detections.'});Object.assign(he,{videoOverlayHelp:'תיבות שמורות ותוויות מעקב מוצגות רק בפריימים שנותחו; הנגן אינו מבצע אינטרפולציה של זיהויים.'});
updateModeOptions();$('inputType').onchange=updateModeOptions;updateRegionControls();translate();loadTimezoneMap();action(async()=>{await refreshMissions();if(missions.length){mission=missions[0].id;$('missions').value=mission;syncMissionConfig();await refreshSchedules();await refreshViews();await load();await poll();}});setInterval(poll,2000);

