$('exportVideoEventTable').onclick=()=>action(async()=>{if(!videoRunId)throw new Error(tr('videoNoRunForEventExport'));const operator=$('videoOperator').value.trim();if(!operator)throw new Error(tr('videoOperator')+' required');const result=await api('/api/video/event-exports',{mission,run:videoRunId,operator});videoEventTableExports=result.files||[];renderVideoEventExports();if(result.status==='completed')message(tr('videoEventTableExported')+' · '+videoEventTableExports.length);else message(tr(result.status==='partial'?'videoEventTablePartial':'videoEventTableFailed')+' · '+(result.errors||[]).join('; '),true);});
